tinymce.PluginManager.add('dynamicblocks', function(editor, url) {

  editor.addButton('dynamictabellen', {
	   text: 'Norm Tabelle',
		icon: 'table',
		id: 'dynamictabellen',
		class: 'dynamicblocks',
		tooltip:'Norm Tabelle',
		stateSelector:"img .dynamicblocks",
		onclick: function() {
			ShowTabeleFenster(CurrTabelleID);
		}
  });
  
  
  /********************************************dynamicvars*******************************************/
  editor.addButton('dynamicvars', {
	   text: 'Variablen',
		icon: 'count',
		image: tinymce.baseURL + '/plugins/dynamicblocks/func.png',
		id: 'dynamicvars',
		class: 'dynamicblocks',
		tooltip:'Dynamische Variablen definieren',
		stateSelector:"img .bvariable",
		onclick: function() {
			ShowFunctionTree(CurrFunctionID);
		}
  });
  
	editor.addButton('dynamicblocks', {
    text: 'Diagramme',
    icon: 'template',
    id: 'dynamicblocks',
    class: 'dynamicblocks',
	tooltip:'Diagramme hinzufügen',
	stateSelector:"img .seite_diagramm",
    onclick: function() {
      // Open window
      editor.windowManager.open({
		width: 500,
		height: 350,
        title: 'Wälen Sie ein Diagrammetyp',
        body: [
          {type: 'container', label  : '',data:"", html  :'<ul><li class="diagramwahl" data-value="lh">LH<br/><img src="images/lh.png" src="images/lh.png"></li>'+
		  '<li data-value="lh" class="diagramwahl">LV<br/><img src="images/lv.png" width="65"></li>'+
		  '<li data-value="mw" class="diagramwahl">MW<br/><img src="images/mw.png" width="65"></li>'+
		  '<li data-value="mwc" class="diagramwahl">MWC<br/><img src="images/mwc.png" width="65"></li>'+
		  '<li data-value="mwdev" class="diagramwahl">MWDEV<br/><img src="images/mwdev.png" width="65"></li>'+
		  '<li data-value="stddev" class="diagramwahl"> STDDEV<br/><img src="images/stddev.png" width="65"></li>'+
		  '</ul><div class="diagramdaten" id="diagramdaten"></div>'}
        ],
        onsubmit: function(e) {
          // Insert content when the window form is submitted
		  
		  chartID= jsonObj['sCharts'].length;
		  chartItemID = SelectedChart + '_' + chartID;		  
				
			var sChart= {};
			sChart["cID"] = jsonObj["sCharts"].length;
			sChart["cSysName"] = chartItemID;
			sChart["cTitle"] = $('#ChartItemTitle_'+chartItemID).val();
			sChart["cType"] = $('#ChartItemType_'+chartItemID).val();
			sChart["cTabelle"] = $('#ChartItemFach_'+chartItemID).val();
			sChart["cVars"]=[];
			
			for(jv=0 ;jv < GetChartVarCount(SelectedChart) ; jv++){
				var VariabelItem='variabel_'+jv;
				var vVAR= {'variabel':$('#'+VariabelItem).val(),'tabelle_ID':sChart["cTabelle"]};	
				sChart["cVars"].push(vVAR);
			}
			jsonObj["sCharts"].push(sChart);
		
		  var ChartObject='<img id="Editor_Chart_'+ SelectedChart +'_'+chartID+'" data-value="'+SelectedChart+'" class="seite_diagramm" src="images/'+SelectedChart+'.png" style="width:100%;height:350px;cursor:help;"/>';
		
          editor.selection.setContent(ChartObject);
		  ShowTools(SelectedChart);
		}
      });
	  $('.diagramwahl').click(function(e) {
		  $('.diagramwahl').addClass('hidden');
		  $(this).removeClass('hidden');
		  SelectedChart=$(this).attr('data-value');
		  setNewChart(SelectedChart,'','','#diagramdaten');
	  });
    }
  });
  
/*****************************************chartFunctions***************************************/
  editor.addButton('chartFunctions', {
      type: 'listbox',
      text: 'Diagramme Funktionen',
      icon: false,
	  id:'chartFunctions',
      onselect: function (e) {
        editor.insertContent(this.value());
      },
      values: [
        { text: 'Menu item 1', value: '&nbsp;<strong>Some bold text!</strong>' },
        { text: 'Menu item 2', value: '&nbsp;<em>Some italic text!</em>' },
        { text: 'Menu item 3', value: '&nbsp;Some plain text ...' }
      ],
      onPostRender: function () {
        // Select the second item by default
        this.value('&nbsp;<em>Some italic text!</em>');
      }
    });

  // Adds a menu item to the tools menu
  editor.addMenuItem('dynamicblocks', {
    text: 'dynamicblocks plugin',
    context: 'tools',
    onclick: function() {
      // Open window with a specific url
      editor.windowManager.open({
        title: 'TinyMCE site',
        url: 'https://www.tinymce.com',
        width: 800,
        height: 600,
        buttons: [{
          text: 'Close',
          onclick: 'close'
        }]
      });
    }
  });

  return {
    getMetadata: function () {
      return  {
        name: "dynamicblocks plugin",
        url: "http://dynamicblocksplugindocsurl.com"
      };
    }
  };
});
